def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    aggressive = 0
    desperate_opp = 0
    rich_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_opp += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0)
                prev_bids.append(b)
                if b >= 100:
                    aggressive += 1

    if not alive:
        return float(min(budget, 8.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / WATER_REQ
    scarce = units < 2.0
    very_scarce = units < 1.5

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if day >= 8:
        danger += 1

    reserve_floor = max(0.0, (10 - day) * 8.0)
    spendable = max(0.0, budget - reserve_floor)

    if danger >= 4:
        bid = max(110.0, highest_prev + 3.0, DAILY_SALARY * 1.45)
    elif very_scarce:
        bid = max(95.0, highest_prev + 2.0, avg_prev + 8.0)
    elif scarce:
        bid = max(62.0, avg_prev + 3.0)
        if aggressive >= 2 or rich_opp >= 2:
            bid = max(bid, highest_prev + 1.5)
    else:
        bid = 18.0
        if desperate_opp >= 2:
            bid = 28.0
        if highest_prev >= 120:
            bid = min(bid, 16.0)

    if hp >= 8 and no_water_days == 0 and not scarce and highest_prev >= 100:
        bid = min(bid, 12.0)

    if spendable > 0:
        bid = min(bid, max(12.0, spendable))
    bid = min(bid, budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 130.0))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    days_left = EPISODE_DAYS - day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        if days_left == 0 and my_status['hp'] < 10:
            return min(my_status['budget'], DAILY_SALARY * 1.5)
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = 0.0

    if days_left == 0:
        if my_status['hp'] < 10:
            bid = my_status['budget']
        else:
            bid = DAILY_SALARY * 0.1
    else:
        if not yesterday_bids:
            if my_status['hp'] <= 3:
                bid = DAILY_SALARY * 0.95
            elif my_status['hp'] <= 6:
                bid = DAILY_SALARY * 0.75
            else:
                bid = DAILY_SALARY * 0.6
        else:
            highest_prev_bid = max(yesterday_bids)

            if my_status['hp'] <= 2:
                bid = max(highest_prev_bid + 15, DAILY_SALARY * 0.98)
            elif my_status['hp'] <= 4:
                bid = max(highest_prev_bid + 10, DAILY_SALARY * 0.9)
            elif my_status['hp'] <= 6:
                bid = max(highest_prev_bid + 5, DAILY_SALARY * 0.75)
            elif my_status['hp'] <= 8:
                bid = max(highest_prev_bid + 2, DAILY_SALARY * 0.65)
            else:
                if day_context['supply'] >= 2 * WATER_REQ:
                    bid = max(highest_prev_bid + 1, DAILY_SALARY * 0.55)
                else:
                    bid = max(highest_prev_bid + 1, DAILY_SALARY * 0.6)

    final_bid = min(my_status['budget'], max(1.0, bid))

    return final_bid

